/**
 * Attendance grid: collects radio changes, updates live counts,
 * supports "Mark all present" and saves all in one bulk WS call.
 *
 * @module     local_sentientia_classroom/attendance
 * @copyright  2026 Airpay Payment Services
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define("local_sentientia_classroom/attendance", [
    "core/str",
    "core/notification",
    "core/ajax"
], function(Str, Notification, Ajax) {
    "use strict";

    var STATUS_KEYS = {0: "absent", 1: "present", 2: "late", 3: "excused"};

    var recountFromGrid = function(root) {
        var counts = {present: 0, late: 0, excused: 0, absent: 0};
        root.querySelectorAll('[data-region="attendance-grid"] tr[data-userid]').forEach(function(row) {
            var checked = row.querySelector('input[type=radio]:checked');
            var s = checked ? parseInt(checked.dataset.status, 10) : 0;
            var key = STATUS_KEYS[s] || "absent";
            counts[key]++;
        });
        Object.keys(counts).forEach(function(k) {
            var el = root.querySelector('[data-counter="' + k + '"]');
            if (el) { el.textContent = counts[k]; }
        });
    };

    var setDirty = function(root, dirty) {
        var hint = root.querySelector('[data-region="dirty-hint"]');
        if (hint) { hint.hidden = !dirty; }
        root.dataset.dirty = dirty ? "1" : "0";
    };

    var handleRadioChange = function(root) {
        return function(event) {
            var t = event.target;
            if (!t.matches('input[type=radio][data-userid]')) { return; }
            setDirty(root, true);
            recountFromGrid(root);
        };
    };

    var markAllPresent = function(root) {
        root.querySelectorAll('[data-region="attendance-grid"] tr[data-userid]').forEach(function(row) {
            var presentRadio = row.querySelector('input[type=radio][data-status="1"]');
            if (presentRadio && !presentRadio.disabled) {
                presentRadio.checked = true;
            }
        });
        setDirty(root, true);
        recountFromGrid(root);
    };

    var saveAttendance = function(sessionid, root) {
        var marks = [];
        root.querySelectorAll('[data-region="attendance-grid"] tr[data-userid]').forEach(function(row) {
            var userid = parseInt(row.dataset.userid, 10);
            var checked = row.querySelector('input[type=radio]:checked');
            var status = checked ? parseInt(checked.dataset.status, 10) : 0;
            if (userid > 0) {
                marks.push({userid: userid, status: status, notes: ""});
            }
        });

        if (marks.length === 0) {
            Str.get_string("no_attendance_yet", "local_sentientia_classroom").then(function(empty) {
                Notification.addNotification({message: empty, type: "warning"});
                return null;
            }).catch(Notification.exception);
            return;
        }

        Ajax.call([{
            methodname: "local_sentientia_classroom_bulk_mark_attendance",
            args: {sessionid: sessionid, marks: marks}
        }])[0].then(function(response) {
            Notification.addNotification({
                message: response.message || "Attendance saved.",
                type: "success"
            });
            setDirty(root, false);
            return null;
        }).catch(Notification.exception);
    };

    var handleClick = function(sessionid, root) {
        return function(event) {
            var trigger = event.target.closest('[data-action]');
            if (!trigger) { return; }
            var action = trigger.dataset.action;
            if (action === "mark-all-present") {
                event.preventDefault();
                markAllPresent(root);
            } else if (action === "save-attendance") {
                event.preventDefault();
                saveAttendance(sessionid, root);
            }
        };
    };

    return {
        init: function(sessionid) {
            var root = document.querySelector('[data-region="airpay-attendance"]');
            if (!root) { return; }
            if (root.dataset.airpayAttendanceInit === "1") { return; }
            root.dataset.airpayAttendanceInit = "1";

            root.addEventListener("change", handleRadioChange(root));
            root.addEventListener("click", handleClick(sessionid, root));

            window.addEventListener("beforeunload", function(e) {
                if (root.dataset.dirty === "1") {
                    e.preventDefault();
                    e.returnValue = "";
                }
            });
        }
    };
});
